"""Generate the SYNTHETIC test fixture (invented records, not real research data).

Deterministic. Covers namesakes, missing author IDs, missing abstracts, missing and
empty reference lists, a large author list, truncation, duplicates and external refs.
"""

import json
import random
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[2] / "pipeline"))
from atlas.collect import record_hash  # noqa: E402

BASE = "https://example.invalid/synthetic/"
rng = random.Random(7)
FIELDS = [("SYNF1", "Synthetic Field Alpha"), ("SYNF2", "Synthetic Field Beta"), ("SYNF3", "Synthetic Field Gamma")]
TOPICS = [(f"SYNT{i}", f"Synthetic topic {i}", FIELDS[i % 3]) for i in range(1, 7)]
PEOPLE = [(f"SYNA{i:02d}", f"Test Person {chr(64 + i)}") for i in range(1, 19)]
PEOPLE.append(("SYNA19", "Test Person A"))  # namesake of SYNA01: distinct ID, must not merge
INST = [("SYNI1", "Example Institute One"), ("SYNI2", "Example Institute Two")]
EXT_REFS = [f"SYNR{i:02d}" for i in range(1, 31)]


def work(i: int) -> dict:
    wid = f"SYNW{i:03d}"
    group = i % 3
    people = [p for k, p in enumerate(PEOPLE) if k % 3 == group]
    authors = rng.sample(people, k=min(len(people), rng.randint(1, 3)))
    auths = [{
        "author_position": "first" if k == 0 else "middle",
        "raw_author_name": name,
        "author": {"id": BASE + pid, "display_name": name, "orcid": None},
        "institutions": [{"id": BASE + INST[k % 2][0], "display_name": INST[k % 2][1], "ror": None, "country_code": "XX"}],
    } for k, (pid, name) in enumerate(authors)]
    pool = EXT_REFS[group * 8:group * 8 + 12]
    refs = [BASE + r for r in rng.sample(pool, k=4)]
    if i > 3:
        refs.append(BASE + f"SYNW{rng.randint(1, i - 1):03d}")
    t = TOPICS[group * 2 + (i % 2)]
    w = {
        "id": BASE + wid, "doi": None, "display_name": f"Synthetic work {i}: placeholder title for testing",
        "publication_year": 2021 + i % 5, "publication_date": f"{2021 + i % 5}-0{1 + i % 9}-15", "type": "article",
        "authorships": auths,
        "topics": [{"id": BASE + t[0], "display_name": t[1], "score": round(0.5 + rng.random() / 2, 3),
                    "subfield": {"id": None, "display_name": None},
                    "field": {"id": BASE + t[2][0], "display_name": t[2][1]},
                    "domain": {"id": None, "display_name": "Synthetic Domain"}}],
        "referenced_works": refs,
        "abstract_inverted_index": {"Synthetic": [0], "abstract": [1], "for": [2], "testing.": [3]} if i % 4 else None,
    }
    return w


works = [work(i) for i in range(1, 37)]
works[5]["referenced_works"] = []           # known-empty reference list
del works[6]["referenced_works"]             # reference field absent
works[7]["authorships"].append({"author_position": "last", "raw_author_name": "Unidentified Contributor",
                                "author": {"id": None, "display_name": None, "orcid": None}, "institutions": []})
works[8]["topics"] = []
big = works[9]
big["authorships"] = [{"author_position": "middle", "raw_author_name": n, "author": {"id": BASE + p, "display_name": n, "orcid": None}, "institutions": []} for p, n in PEOPLE]
big["is_authors_truncated"] = True
works.append(dict(works[0]))                 # duplicate ID

out = Path(__file__).parent / "synthetic_raw"
out.mkdir(exist_ok=True)
hashes = {}
with (out / "works.jsonl").open("w") as fh:
    for w in works:
        hashes.setdefault(w["id"], record_hash(w))
        fh.write(json.dumps(w, sort_keys=True) + "\n")
(out / "manifest.json").write_text(json.dumps({
    "collectionId": "synthetic-fixture", "provider": "SYNTHETIC FIXTURE", "synthetic": True,
    "attribution": "SYNTHETIC FIXTURE: invented records for tests and development only. Not real research data.",
    "query": {"note": "generated by tests/fixtures/make_synthetic.py"}, "retrievedAt": "2000-01-01T00:00:00+00:00",
    "status": "complete", "statusDetail": "", "providerTotal": None, "warnings": [], "workHashes": hashes,
}, indent=2, sort_keys=True))
print(out)
